  var showMap = function(latitude, longitude) {
    const popup = new Popup({
      id: "map",
      title: "",
      content: "",
      sideMargin: "2.9vw",
      titleColor: "#fff",
      textColor: "#fff",
      backgroundColor: "#222",
      closeColor: "#fff",
      fontSizeMultiplier: 1.2,
      linkColor: "#888",
      hideCallback: () => {
        window.map.remove();
        document.querySelector(".popup").remove();
      }
    });
    popup.show();
    const mapContainer = document.createElement("div");
    mapContainer.id = "map";
    mapContainer.style.width = "100%";
    mapContainer.style.height = "400px";
    document.querySelector(".popup-body").appendChild(mapContainer);
    window.map = L.map("map").setView([latitude, longitude], 13);
    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
      attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
    }).addTo(map);
    L.marker([latitude, longitude]).addTo(map).bindPopup("Approx. Location").openPopup();
  };
